    'your_own_api_you_choose_scope_by_scope_which_of_its_sco_6f77f332' => 'Ditt eget API. Du velger for hvert tilgangsomfang om apper som registreres av organisasjoner, kan be om det.',
    'your_own_credentials_with_each_provider_offered_on_ever_82ce1e08' => 'Din egen legitimasjon for hver leverandør, tilgjengelig på alle påloggingssider i miljøet. Alle organisasjoner arver den.',
    'your_own_credentials_with_each_provider_offered_to_ever_d1715d1a' => 'Din egen legitimasjon for hver leverandør, tilgjengelig for alle i miljøet. Hver organisasjon arver den.',
    'your_receiver_keeps_the_same_secret_used_exactly_as_wri_431d83f5' => 'Mottakeren beholder samme hemmelighet og bruker den nøyaktig som skrevet, inkludert whsec_-prefikset, som HMAC-nøkkel for X-Cbox-Signature.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'Påloggingssiden har din logo og dine farger. Personer skriver inn passordet sitt der, så siden bør tydelig være din.',
    'your_organization_its_projects_team_keys_and_billing_si_152a2f42' => 'Arbeidsområdet ditt med prosjekter, team, nøkler og fakturering. Pålogging til appene dine angis i konsollen for hvert miljø.',
    'a_feature_flag_is_a_switch_your_apps_ask_about_for_one_9a43d208' => 'Et funksjonsflagg er en innstilling appene spør om for én person i én organisasjon. Aktiver det for bestemte brukere, organisasjoner eller en prosentandel av alle brukere. Alle apper får samme svar fra tokenets `feature_flags`-claim eller evalueringsendepunktet, uten ny utrulling. En brukerregel går foran en organisasjonsregel, som går foran utrullingen, som går foran standardverdien.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'En nøkkel lar skriptene og integrasjonene dine kalle en apps API som deg uten pålogging. Den kan aldri gjøre mer enn du kan i appen. Hvis tilgangen din reduseres, mister nøkkelen de samme rettighetene. Nøkkelen vises én gang, så kopier den når du oppretter den, og tilbakekall den straks hvis den lekker eller ikke lenger brukes.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'En tillatelse er én ting en rolle kan gjøre, som å opprette fakturaer eller lese rapporter. Du kan definere egne tillatelser her uten kode og sette dem sammen til roller. Apper kan også registrere sine automatisk, slik at listen følger det appen faktisk håndhever. Egne tillatelser kan du endre; miljøets delte tillatelser kan du bruke, men ikke endre.',
    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'En telefon med autentiseringsappen svarer på godkjenningsforespørsler og varsler når noen logger på som deg. Registrer den ved å skanne koden. Fjern den her umiddelbart hvis du mister telefonen; da kan den ikke godkjenne noe mer.',
    'a_project_is_one_idp_product_this_organization_owns_and_d87379c8' => 'Et prosjekt er et identitetsleverandørprodukt som arbeidsområdet eier, og miljøene hører til prosjektet. Før arbeidsområdet oppretter et prosjekt i sin egen konsoll, finnes det ingenting å velge eller åpne her. Denne siden oppretter ikke et prosjekt på vegne av arbeidsområdet.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Et prosjekt er ett av produktene dine, med eget abonnement, pålogging og miljøer som produksjon og staging. Åpne et miljø herfra for å administrere det. Opprett et nytt prosjekt når du lanserer et produkt som skal driftes og faktureres separat.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'En rolle er en arbeidsoppgave appene dine forstår, som redaktør eller supportmedarbeider. Du bestemmer hvem som har hvilken rolle her, og hver app bestemmer hva rollene tillater. Rollene følger personen inn i tilkoblede apper, slik at du kan gi og trekke tilbake tilgang på ett sted.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'En gjennomgang der du kontrollerer hvem som har hvilke roller, og bekrefter at de fortsatt trenger dem. Rettigheter hoper seg lett opp når personer bytter team, men beholder gamle tilganger. Gjennomgangen hjelper deg å rydde opp. Tilbakekallinger brukes når den avsluttes, og hele runden dokumenteres for revisoren.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Et skjema beskriver hvordan en handlings hendelser skal se ut: måltyper og metadata. Hendelser med skjema kontrolleres når de mottas. Uten skjema godtas de slik de sendes, med mindre streng modus er aktivert.',
    'an_organization_is_one_signed_up_company_s_home_on_this_b98406a0' => 'Et arbeidsområde er et registrert selskaps område i installasjonen, med prosjekter, miljøer og team. Åpne det for å administrere produkter og miljøer. Suspensjon logger ut medlemmene og stopper pålogging i alle tilhørende miljøer.',
    'access_accumulates_people_change_teams_and_keep_what_th_cd6b423c' => 'Tilgang hoper seg opp. Personer bytter team, men beholder gamle rettigheter til en revisor spør. En gjennomgang tar et øyeblikksbilde av gjeldende tildelinger og krever en beslutning om hver rettighet fortsatt trengs.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Legg personen til i en organisasjon nedenfor for å gi tilgang der. Hvis appene ikke har egne kundeområder, kan du i stedet gi en administrasjons- og supportrolle som gjelder i hele miljøet.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'En administrasjons- og supportrolle gis til egne ansatte, som support og drift, for hele miljøet. Den gjelder i alle organisasjoner og kan ikke ses, tildeles eller fjernes av administratorene deres. En approlle som tildeles på denne måten, gjelder fortsatt bare den appen.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'En administrasjons- og supportrolle gis til egne ansatte for hele miljøet. Den gjelder i alle organisasjoner og kan ikke ses eller endres av administratorene deres.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'En agent er programvare som jobber i miljøet med en administrasjonsnøkkel: en KI-assistent som Claude Code eller Cursor, en intern bot eller backenden din. Gi hver agent en egen nøkkel med bare nødvendige tilgangsomfang. Bestem hvilke handlinger som krever godkjenning, og tilbakekall nøkkelen straks arbeidet er ferdig eller noe virker galt.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'Et API er en tjeneste som mottar tilgangstokener, for eksempel https://api.example.com. Registrer det med tilgangsomfangene det forstår. Du bestemmer hvilke av dem apper registrert av organisasjonene kan be om. Et token for API-et angir adressen som mottaker, og tjenesten kontrollerer denne.',
    'an_environment_is_a_fully_isolated_identity_service_wit_993d6053' => 'Et miljø er en helt isolert identitetstjeneste med egne brukere, nøkler, pålogging og utsteder. Her vises alle miljøene i installasjonen med arbeidsområdet som eier dem. Opprett et miljø, velg det i konsollen og konfigurer den første organisasjonen og administratoren.',
    'an_environment_is_fully_isolated_its_own_users_keys_sig_bc49f6f9' => 'Et miljø er helt isolert med egne brukere, nøkler, pålogging og utsteder. Opprett det første ovenfor og konfigurer deretter en organisasjon med administrator.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'En identitetsleverandør som importerer tjenesteleverandørmetadata, bruker denne URL-en i stedet for separate verdier for entitets-ID og ACS-URL. Den fungerer allerede før identitetsleverandørens opplysninger er fylt ut.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'En organisasjon samler brukere, påloggingsmetoder og roller. Opprett en ovenfor, eller konfigurer miljøets første organisasjon og administrator fra siden Miljøer.',
    'an_organization_s_own_provider_replaces_the_environment_5a3f34fa' => 'Organisasjonens egen leverandør erstatter miljøets på påloggingssiden. Organisasjoner som har slått av miljøets leverandør, vises også. Det fjerner bare knappen; det er kravet om SSO som hindrer andre påloggingsmåter.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'API-nøkler og tokener for eksterne tjenester som apper og agenter trenger, lagres kryptert her i stedet for i hver apps konfigurasjon. Legg inn en hemmelighet én gang og gi bestemte apper rett til å bruke den. Den vises aldri igjen, så forny den hvis du mister den.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'API-nøkler som appene og agentene dine bruker hos andre tjenester. Hver verdi lagres kryptert, gis bare til uttrykkelig autoriserte apper og vises aldri igjen etter lagring.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Apper som ber om å handle på vegne av en av brukerne dine. Hver bruker godkjenner sine egne forespørsler. Avvis bare her hvis det ser ut som misbruk; avslaget registreres i revisjonsloggen.',
    'apps_that_keep_their_own_user_list_drift_out_of_step_th_fc8e8671' => 'Apper med egne brukerlister kommer ut av synk når noen begynner eller slutter. En SCIM-tilkobling sender hver endring med en gang, også fratredelser som ellers lett blir glemt.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID sender en signert melding til endepunktet etter en hendelse, som et nytt medlem eller en rolleendring. Systemene dine kan dermed reagere uten stadige forespørsler. Leveringer forsøkes på nytt ved behov. Endepunktet varsles i etterkant og kan ikke påvirke handlingen.',
    'certify_what_is_still_needed_revoke_what_is_not_nothing_31e57691' => 'Bekreft det som fortsatt trengs, og trekk tilbake resten. Ingenting brukes før gjennomgangen avsluttes. En tilbakekalt administrasjons- og supportrolle fjernes da i alle organisasjoner samtidig.',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Velg SCIM hvis leverandøren sender data til oss, Google Workspace eller Entra hvis vi skal hente dem, eller HR-systemet ditt, som Workday, BambooHR, Rippling, HiBob eller Personio, slik at personer får konto på startdatoen.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code åpner nettleseren for pålogging her og spør hva du vil tillate. Ingen nøkkel må oppbevares. Alle MCP-klienter som logger på med OAuth, fungerer på samme måte med denne URL-en.',
    'comma_or_space_separated_a_scope_you_type_is_unowned_it_c5513416' => 'Skill med komma eller mellomrom. Et innskrevet tilgangsomfang har ingen API-eier og overføres uendret til appens tokener. Det kan aldri angi et registrert API som mottaker; bruk listene ovenfor til det.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'Opprette, endre, aktivere, deaktivere og slette SSO-tilkoblinger, kreve SSO for en organisasjon og bekrefte og aktivere SSO-ruting for e-postdomenene. Endrer hvordan personer logger på.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Oppretter organisasjonen, eieren, det første produktet og produktets produksjonsmiljø. Eieren får en lenke på e-post for å velge sitt eget passord; du velger ikke et for vedkommende.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Definere, erstatte og slette skjemaer for validering av revisjonshendelser og endre lagringstiden. Kortere lagringstid sletter eldre hendelser permanent.',
    'deleting_this_organization_tears_down_every_project_and_0d442c8e' => 'Hvis arbeidsområdet slettes, fjernes alle prosjektene og miljøene det eier. For å beskytte aktive identitetsleverandører er dette ikke selvbetjent. Kontakt support for å fortsette.',
    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Hver organisasjon er en bedrift eller et team som bruker produktet, med egne medlemmer, roller, domener og SSO. Opprett én per bedrift som registrerer seg. Åpne den for å administrere medlemmer, invitasjoner og bekreftede domener, eller for å suspendere den.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Hver pipeline lar personer koble til egne kontoer hos tjenester som GitHub, Google eller Slack. Tokenene lagres kryptert og holdes oppdaterte her. Autoriserte apper ber om et gyldig token når de kaller tjenesten som personen, og lagrer aldri et selv.',
    'each_project_in_your_organization_has_its_own_plan_and__0a007c9c' => 'Hvert prosjekt i arbeidsområdet har eget abonnement og miljøkvote. Disse vises sammen med månedens bruk: organisasjoner, fakturerte SSO-tilkoblinger og pålogginger. Prisingen teller månedlig aktive brukere og bedriftstilkoblinger som SSO og SCIM. Sandboxmiljøer har ingen tilkoblingsavgift.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'Hele miljøet: alle med en konto i miljøet kan logge på appen, uansett organisasjon. Velg en organisasjon hvis det ikke er meningen.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Slette en person permanent (GDPR artikkel 17): legitimasjon, økter, medlemskap og personopplysninger slettes, og kontoen pseudonymiseres. Kan ikke angres.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Vurderes i rekkefølge: blokkeringslisten, tillatelseslisten, dine regler ovenfra med første treff som avgjørende, deretter de innebygde reglene der det strengeste treffet avgjør. Uten treff tillates tilgang.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Hver handling godtas slik appen sender den. Legg til et skjema for å kontrollere hendelsene når de mottas. En konsistent logg sikres når hendelsen skrives, ikke først når den leses.',
    'every_administrative_change_members_roles_connections_a_ef641619' => 'Hver administrativ endring av medlemmer, roller, tilkoblinger eller apper registreres her med en gang, med hvem som gjorde den og når. Ingen konfigurasjon er nødvendig.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'API-nøkler i appkonfigurasjoner eller miljøfiler kan ikke fornyes sentralt eller trekkes tilbake raskt. Her lagres de kryptert, tildeles per app og kan tilbakekalles med ett klikk.',
    'every_api_key_the_people_in_this_organization_have_crea_b802c1e7' => 'Alle API-nøkler som personer i organisasjonen har opprettet for appene. Tilbakekall nøkler som har lekket eller ikke lenger brukes. Personer oppretter egne nøkler under Min konto.',
    'every_api_key_the_people_in_this_organization_have_crea_51e4cae3' => 'Alle API-nøkler som personer i organisasjonen har opprettet for appene: innehaver, app, tillatelser og siste bruk. En nøkkel kan bare gjøre det innehaveren kan, og slutter å fungere når personen forlater organisasjonen. Tilbakekall lekkede eller ubrukte nøkler. Hver person oppretter sine egne under Min konto.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Hver app som logger på personer gjennom Cbox ID eller kaller API-et, registreres her og får egen legitimasjon. Registrer én per app og miljø. Del aldri legitimasjon mellom dem, slik at én kan tilbakekalles uten at de andre slutter å fungere.',
    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Alle nettlesere og enheter der du er pålogget, apper du har gitt tillatelse til å handle for deg, og nylige pålogginger og sikkerhetsendringer. Hvis noe er ukjent, logg ut økten eller trekk tilbake appens tilgang, og endre deretter passordet.',
    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'Hver endring i organisasjonen: hvem som gjorde hva, med hvilket objekt og når. Oppføringene lenkes med hashverdier, slik at en endret eller slettet oppføring bryter kjeden og oppdages. Loggen er bevisst skrivebeskyttet og er dokumentasjonen du gir en revisor.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Alle tilkoblinger mellom Cbox ID og andre systemer på ett sted: SSO, sosial pålogging, katalog- og HR-synkronisering, utgående provisjonering, SAML-apper, webhooks, hooks, loggstrømmer og pipelines. Hvert katalogkort åpner riktig oppsettside. Tilkoblinger viser alle aktive forbindelser med status, feilende først.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Alle organisasjoner i miljøet som er valgt i konsollen, som et tre med forhandlere, organisasjonene de administrerer og underenheter. Opprett eller suspender en organisasjon, eller flytt den under en annen overordnet organisasjon.',
    'every_page_you_open_from_now_on_organizations_usage_org_7ba726d3' => 'Alle sider du åpner fra nå av, som organisasjoner, bruk og organisasjonsdetaljer, leser dataene fra dette miljøet. Ingenting endres i noen av miljøene.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Alle personer med en identitet i miljøet, uansett organisasjon. Åpne en person for å tilbakestille passord eller tofaktor, avslutte økter, deaktivere kontoen, endre organisasjoner og roller eller slette personen permanent etter en forespørsel om sletting.',
    'every_revoke_recorded_on_this_review_is_applied_for_rea_1abdd266' => 'Alle tilbakekallinger i gjennomgangen brukes nå. Oppføringer som ikke er vurdert, følger gjennomgangens policy, som som standard trekker tilbake tilgangen. Dette kan ikke angres.',
    'every_secret_that_signs_this_app_in_right_now_only_a_ha_6aceec1d' => 'Alle hemmeligheter som for øyeblikket autentiserer appen. Bare en hash av hver lagres. Listen viser de fire siste tegnene, slik at du kan identifisere hvilken hemmelighet en installasjon bruker.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Alle tokener som er utstedt med den, tilbakekalles nå, og nye pålogginger kan ikke bruke den. Apper som kontrollerer tokenene selv, godtar dem til de utløper, senest ved øktens slutt.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Alle påloggingsmetoder med status og hvor de endres: passord, passnøkler, e-postlenke, sosial pålogging, Enterprise SSO og andre faktor. De fleste styres av miljøet, mens SSO-tilkoblinger tilhører organisasjonene. Hvis installasjonen begrenser en metode, vises det sammen med innstillingens navn.',
    'every_organization_on_this_install_open_one_to_walk_its_f0bd9340' => 'Alle arbeidsområder i installasjonen. Åpne et for å administrere produkter og miljøer. Suspensjon logger ut medlemmene og stopper autentisering i alle tilhørende miljøer.',
    'everyone_who_administers_this_organization_the_built_in_69802df4' => 'Alle som administrerer arbeidsområdet, deres innebygde rolle (Eier, Administrator, Utvikler, Medlem eller Leser) og tilgjengelige miljøer. Inviter på e-post og gi bare miljøene arbeidet krever.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Alle som kan logge på organisasjonen, og invitasjonene du har sendt som ennå ikke er godtatt. Inviter på e-post. Personene setter opp sin egen pålogging, så du aldri trenger å håndtere passordene deres.',
