    '_part1_a_code_can_be_taken_by_a_sim_swap_or_number_port_690b2597' => ':part1 En kode kan stjeles ved SIM-bytte eller uautorisert nummerportering, fanges opp i telefonnettet eller skrives inn på en troverdig falsk innloggingsside. Den er likevel langt sikrere enn bare et passord. Aktiver den for personer som ikke kan bruke en autentiseringsapp eller en passkey.',
    '_part1_a_logo_linked_from_another_site_told_that_site_a_dcac9b85' => ':part1 En logo som ble hentet fra et annet nettsted, avslørte for nettstedet hvem som åpnet innloggingssiden din. Derfor viser vertsbaserte sider nå bare bilder som er lastet opp her. Last den opp under :part2 nedenfor, eller fjern den for å skjule dette varselet.',
    '_part1_a_role_is_a_label_stamped_into_the_token_the_one_92a78021' => ':part1 En rolle er en betegnelse i tokenet. Roller en app definerer, er skrivebeskyttet her; de øvrige definerer du selv. Hvert medlem har også nøyaktig én :part2 :part3 :part4 (eier, administrator, utvikler, medlem eller leser), som avgjør hva personen kan administrere i denne konsollen.',
    '_part1_already_belongs_to_another_api_in_this_environme_bab95da8' => '«:part1» tilhører allerede et annet API i dette miljøet. En tokenforespørsel angir et tilgangsområde bare ved nøkkelen, så hver nøkkel kan bare tilhøre ett API.',
    '_part1_belong_to_an_api_this_app_may_not_use_they_are_l_99264721' => ':part1 tilhører et API denne appen ikke kan bruke. De utelates fra alle tokener. Fjern dem fra de innskrevne tilgangsområdene.',
    '_part1_can_sign_in_with_passwords_or_with_this_connecti_ebadb8e1' => ':part1 kan logge inn med passord eller med denne tilkoblingen. Hvis engangspålogging kreves, avvises alle andre påloggingsmåter, slik at heller ikke allerede utstedte tilgangsmidler kan omgå leverandøren du nettopp satte opp. De fleste bedrifter som kobler til en IdP, ønsker dette, men les først hva det innebærer.',
    '_part1_has_no_permissions_yet_so_part2_part3_arrives_em_a819e0c7' => ':part1 har ingen tillatelser ennå, så :part2 er :part3 tomt. Rollenavnet finnes fortsatt og kan brukes.:part4',
    '_part1_is_already_set_up_for_this_organization_change_i_dea89857' => ':part1 er allerede satt opp for denne organisasjonen. Endre tilgangsopplysningene, eller fjern tilkoblingen først.',
    '_part1_is_no_longer_offered_anyone_who_signed_in_with_i_b1a43020' => ':part1 tilbys ikke lenger. Alle som logget inn med den, beholder kontoen sin og kan fortsatt bruke passordet.',
    '_part1_is_off_on_every_sign_in_page_its_credentials_are_2dc58cfc' => ':part1 er slått av på alle innloggingssider. Tilgangsopplysningene beholdes, slik at du kan slå den på igjen.',
    '_part1_is_off_on_this_organization_s_sign_in_page_its_c_5a7d1345' => ':part1 er slått av på denne organisasjonens innloggingsside. Tilgangsopplysningene beholdes, slik at du kan slå den på igjen.',
    '_part1_is_your_only_way_to_sign_in_set_a_password_or_ad_968a0fd3' => ':part1 er din eneste påloggingsmåte. Angi et passord eller legg til en passkey før du kobler den fra.',
    '_part1_is_your_organization_s_single_sign_on_it_is_how_a02887f1' => ':part1 er organisasjonens engangspålogging. Det er slik organisasjonen identifiserer deg, så tilkoblingen kan ikke fjernes her.',
    '_part1_its_team_is_administered_under_organization_team_6abad4af' => ':part1 Teamet administreres under Arbeidsområde › Team av noen med en arbeidsområderolle, ikke herfra.',
    '_part1_part2_nothing_here_is_set_by_part3_yet_change_an_a8ead075' => ':part1 :part2 Ingenting her styres av :part3 ennå. Hvis du endrer noe nedenfor, blir det organisasjonens egen regel.',
    '_part1_part2_up_to_date_part3_deprovisioned_part4_part5_5604a19e' => ':part1 :part2 oppdaterte, :part3 avprovisjonerte,:part4 :part5 hoppet over, :part6 grupper :part7.',
    '_part1_part2_update_your_receiver_first_from_the_next_a_d1d60a6e' => ':part1 :part2 Oppdater mottakeren først: Fra neste forsøk avviser den alle leveranser den ikke kan verifisere.',
    '_part1_refuses_the_sign_in_unless_this_matches_exactly_8d9cdd26' => ':part1 avviser påloggingen hvis dette ikke samsvarer nøyaktig. Verdien beholdes for dette oppsettet, så du kan lime den inn i :part2 nå og lagre her etterpå.',
    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1 – økter, passkeys og andrefaktorer, profiler hos identitetsleverandører, katalogdata, utstedte tokener, rolletildelinger og revisjonshistorikk beholdes og kan aktiveres igjen.',
