    'what_an_app_may_be_allowed_to_do_at_this_api_only_part1_c0ec6f18' => 'Hva en app kan få gjøre i dette API-et. Bare egne apper fra :part1 kan ha disse tillatelsene.',
    'what_is_part1_00d3f3e7' => 'Hva er :part1?',
    'what_you_are_administering_and_the_details_your_apps_ne_23bc71ef' => 'Det du administrerer, og opplysningene appene dine trenger for integrasjonen. :part1',
    'withdraw_access_for_part1_10961483' => 'Trekk tilbake tilgangen til appen :part1',
    'withdraw_the_invitation_to_part1_13c82934' => 'Trekk tilbake invitasjonen til :part1',
    'withdraw_the_invitation_to_part1_fafedcae' => 'Trekk tilbake invitasjonen til :part1?',
    'you_can_also_part1_part2_part3_53f32513' => 'Du kan også :part1 :part2 .:part3',
    'you_can_turn_it_off_again_on_part1_part2_sessions_that_89d71a9d' => 'Du kan slå det av igjen på :part1 :part2. Avsluttede økter forblir avsluttet.',
    'you_hold_no_permissions_in_part1_so_a_key_would_identif_2c680207' => 'Du har ingen tillatelser i :part1, så en nøkkel ville bare identifisere deg der.',
    'your_endpoint_verifies_the_part1_header_on_each_request_b7ca1bb8' => 'Endepunktet ditt verifiserer headeren :part1 i hver forespørsel med denne hemmeligheten.',
    'your_roles_using_permission' => 'I :count av rollene dine|I :count av rollene dine',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Alt organisasjonen har satt opp, og det som gjenstår. Sjekklisten viser den faktiske tilstanden. Hvert trinn merkes automatisk som fullført når det er ferdig.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Hele merkevareopplevelsen på én side: logo, nettleserikon, farger, skrifttype og hjørner for den vertsbaserte innloggingen med direkte forhåndsvisning, samt produktnavn, e-postavsender og velkomstmelding. Angi innstillingene én gang for hele miljøet, så arves de av alle organisasjoner. Du kan også gi en organisasjon sitt eget utseende på fanen Profilering.',
    'from_the_next_attempt_blocks_refuse_sign_ins_and_sign_u_e89996c3' => 'Fra neste forsøk avviser blokkeringer innlogginger og registreringer i dette miljøet, mens kontrollkrav krever ytterligere verifisering. En feil regel kan stenge virkelige personer ute.',
    'grant_one_to_the_people_who_support_or_run_your_apps_an_3991d001' => 'Gi en til folk som støtter eller kjører appene dine. En apps egen rolle når bare den appens tokens; en rolle for alle apper når hver og en av dem.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Antallet organisasjoner, brukere, SSO-tilkoblinger, apper og brukersynkroniseringer i miljøet, med lenker til hver sin side. Snarveiene nedenfor lar deg opprette det som oftest trengs: en organisasjon, en bruker, en SSO-tilkobling eller en app.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Antallet personer som har logget inn, og hvor ofte appene dine har kalt API-et de siste 30 dagene. Oversikten hjelper deg å vurdere belastningen og oppdage avvik. Den er ikke en faktura.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Hvor ofte data hentes, og hvilke felter fra HR-systemet som kopieres til hver person, for eksempel kostnadssted eller lokasjon. Hvis du endrer feltene, blir neste kjøring en fullstendig synkronisering.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Slik eksporteres revisjonsloggen fra Cbox ID: En planlagt eksport sender nye oppføringer til SIEM-systemet eller arkivet ditt hvert femte minutt. En daglig oppbevaringsjobb oppretter et kontrollpunkt i loggen uten å slette noe. Her kan du hente en persons revisjonshistorikk for en innsynsforespørsel etter GDPR eller kontrollere i en miljøkonsoll at eksportene kjører.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Hvis appen senere angir en annen URL, trekkes godkjenningen tilbake, og du blir spurt på nytt. En endring av hvor passord sendes, skal ikke skje uten godkjenning. Delegert innlogging brukes under overgangen til det nye systemet. Når få personer er igjen i det gamle systemet, deaktiverer du den og sender dem en lenke for å tilbakestille passordet.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Knappen fjernes og tilgangsopplysningene slettes. Alle som har logget inn med tilkoblingen, beholder kontoen sin og kan fortsatt bruke passordet. Slå av tilkoblingen i stedet hvis du vil beholde tilgangsopplysningene.',
    'its_scopes_go_with_it_apps_that_held_them_keep_them_as_bf31a699' => 'Tilgangsområdene fjernes også. Apper som hadde dem, beholder dem som innskrevne tilgangsområder som ikke lenger gir tilgang til dette API-et. Tokener som allerede er utstedt, fortsetter å fungere til de utløper.',
    'keys_for_an_environment_s_management_api_run_one_enviro_6197b6d2' => 'Nøkler til et miljøs administrasjons-API: administrer organisasjoner, medlemmer, invitasjoner, roller og apper i ett miljø fra din egen backend. Hver nøkkel har uttrykkelig angitte tilgangsområder.',
    'keys_this_organization_s_people_have_created_for_its_ap_9d7e0611' => 'Nøkler organisasjonens brukere har opprettet for appene, med tillatelsene til hver nøkkel. Brukerne oppretter sine egne nøkler. Tilbakekall nøkler som har lekket eller ikke lenger brukes.',
    'leave_it_empty_for_almost_every_provider_its_id_tokens_e39d64b9' => 'La feltet stå tomt for nesten alle leverandører. ID-tokenene deres verifiseres mot signeringsnøklene som publiseres i discovery-dokumentet (jwks_uri), også når nøklene roteres. Lim bare inn leverandørens offentlige PEM-nøkkel hvis den ikke publiserer noen nøkler.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'La brukere logge inn med en konto de allerede har. Sett opp en leverandør én gang for miljøet, så tilbys den av alle organisasjoner. En organisasjon kan i stedet bruke egne tilgangsopplysninger eller slå av en leverandør.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'La brukerne av appene dine koble til sine egne GitHub-, Google-, Slack- eller Salesforce-kontoer, slik at appene kan kalle disse API-ene på deres vegne. Tokenene lagres kryptert, fornyes her og gjøres midlertidig tilgjengelige bare for appene du gir tillatelse til.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Lar brukerne dine logge inn med sin eksisterende bedriftskonto hos Microsoft Entra ID, Okta eller Google Workspace i stedet for et eget passord her. Du kobler til identitetsleverandøren én gang og bekrefter e-postdomenene dine. Alle med disse domenene sendes deretter til leverandøren for innlogging.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Innlogging med Entra ID, Okta eller Google Workspace er tilgjengelig i Enterprise-abonnementet. Kontakt kundeansvarlig for å aktivere det for denne organisasjonen.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Fortsatt gyldige lenker som er gitt til organisasjonens IT-administrator. En tilbakekalt lenke slutter å virke umiddelbart. Oppsett som allerede er gjort gjennom lenken, beholdes.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Søker etter en organisasjon via navn eller kortnavn, eller en bruker via navn eller e-post, i alle miljøene i installasjonen og ikke bare miljøet konsollen viser. Bruk søket når noen ber om hjelp og du ikke vet hvilket miljø personen er i.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Metadataskjemaer bruker et delsett av JSON Schema: et objekt med egenskaper av typen tekststreng, tall, heltall, boolsk verdi eller null, med regler for tillatte verdier, lengde, verdiområde, mønster og format. En lagret endring oppretter en ny versjon. Allerede registrerte hendelser beholder versjonen de ble validert mot.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Sender hver nye oppføring i revisjonsloggen direkte til sikkerhetsteamets verktøy, for eksempel et SIEM-system. Sett dette opp slik at undersøkelser kan starte i verktøyene teamet allerede bruker, uten først å be om en eksport. Levering skjer minst én gang, så enkelte duplikater kan forekomme.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'For de fleste integrasjoner passer webhooks bedre. De kjører etter hendelsen og kan ikke blokkere prosessen. Bruk en hook bare når ditt eget system må kunne påvirke en innlogging eller utstedelsen av et token mens det skjer.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Ingen ny hemmelighet utstedes. Fra neste leveringsforsøk, også ved nye forsøk, brukes headerne fra den andre metoden. En mottaker som ikke er oppdatert, vil da avvise hver levering.',
    'nobody_is_on_this_organization_it_has_no_owner_so_nobod_0a51d66d' => 'Arbeidsområdet har ingen medlemmer og ingen eier, så ingen kan logge inn for å administrere det. Dette tyder på en feil ved opprettelsen som bør undersøkes, ikke bare en tom liste.',
    'nothing_is_always_refused_and_nothing_skips_the_rules_d_6699d9d9' => 'Ingen oppføringer avvises alltid eller unntas fra reglene. Blokker et adresseområde som har vært brukt til angrep, eller unnta kontornettverket fra reglene for innloggingshyppighet.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Viser Google, GitHub, Apple og andre leverandører som knapper på innloggingssiden for personer som heller vil bruke en eksisterende konto enn å lage enda et passord. Sett opp en leverandør én gang for miljøet, så tilbys den av alle organisasjoner. En organisasjon kan bruke egne tilgangsopplysninger eller slå av en leverandør. Du oppgir tilgangsopplysningene; resten fylles ut automatisk. En e-postadresse fra en leverandør er aldri nok alene til å få tilgang til en eksisterende konto her.',
    'on_for_this_percentage_of_everyone_the_rules_above_do_n_6ca1e886' => 'Aktivert for denne andelen av alle som ikke omfattes av reglene ovenfor. En stabil hash av bruker-ID-en velger de samme personene hver gang; en økning legger bare til flere. La feltet stå tomt hvis ingen gradvis utrulling skal skje.',
    'one_marked_event_siem_stream_test_sent_now_with_this_st_c0cf0c4a' => 'Én merket hendelse (siem.stream.test) sendes nå med strømmens innstillinger og tilgangsopplysninger, uten kø og uten nye forsøk. Hvis det lykkes, fjernes også markeringen «Handling kreves».',
    'one_per_line_including_the_scheme_https_app_example_com_71de2531' => 'Én oppføring per linje, inkludert protokoll, for eksempel https://app.example.com. Hvis en linje er ugyldig, avvises hele listen. Feilaktige linjer fjernes ikke uten beskjed.',
    'one_type_per_resource_type_its_relation_s_below_it_a_re_18943de8' => 'Én `type` per ressurstype, med tilhørende `relation`-oppføringer under. En relasjon avgjøres av subjekter som er angitt direkte i en tuppel ([user, group#member]), en annen relasjon (owner), en relasjon på et overordnet objekt (viewer from parent) eller en kombinasjon med or, and eller but not.',
    'one_organization_on_this_install_its_team_its_projects__42711bef' => 'Ett arbeidsområde i installasjonen med teamet, prosjektene og alle miljøene som tilhører prosjektene. Hvis arbeidsområdet suspenderes, logges medlemmene ut og autentisering stoppes i alle disse miljøene.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Bare for leverandører som ikke publiserer signeringsnøkler (jwks_uri) i discovery-dokumentet. Ellers hentes nøklene derfra, også etter rotasjon. Oppgi en offentlig PEM-nøkkel. Den lagres kryptert og vises aldri igjen. La feltet stå tomt for å beholde gjeldende nøkkel.',
    'only_the_active_members_of_the_organization_you_choose_a4a82dec' => 'Bare aktive medlemmer av den valgte organisasjonen kan logge inn i denne appen. Alle andre avvises, og avslaget registreres i revisjonsloggen.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Organisasjonsdetaljer i målmiljøet: medlemmer, SSO, domener, tildelte rettigheter og nylig aktivitet. Det eneste som kan endres på denne siden, er organisasjonens status.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Organisasjoner, brukere og aktive økter i alle miljøene i installasjonen, samt organisasjonene med flest medlemmer. Visningen leser bare data og endrer aldri hvilket miljø konsollen viser.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Velg rammeverket du bygger med, så opprettes en app med videresending til den lokale utviklingsserveren, miljøvariabler du kan lime inn, og kode for innlogging. Siden venter til noen faktisk logger inn. Nedenfor finner du stegene som gjør appen til et produkt: profilering, organisasjoner, SSO, en agent, en kollega og produksjon. Hvert steg merkes automatisk som fullført ut fra innholdet i miljøet, aldri manuelt.',
    'platform_operators_administer_every_organization_and_en_36866fb1' => 'Plattformoperatører administrerer alle arbeidsområder og miljøer i installasjonen på et overordnet nivå. Legg bare til operatører som har ansvar for selve installasjonen, og suspender tilgangen når dette ikke lenger er oppgaven deres.',
    'point_an_identity_provider_at_our_scim_endpoint_connect_9f06ef10' => 'Koble en identitetsleverandør til SCIM-endepunktet vårt, koble til Google Workspace eller Microsoft Entra, eller koble til HR-systemet ditt: Workday, BambooHR, Rippling, HiBob eller Personio. Vi henter personalopplysningene fra de tilkoblede systemene etter en tidsplan.',
    'prove_which_email_domains_your_organization_owns_a_veri_a1717fad' => 'Bekreft hvilke e-postdomener organisasjonen eier. Et bekreftet domene kan sende alle med en adresse på domenet direkte til organisasjonens SSO-tilkobling.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar vurderer hver innlogging og registrering: forsøk med stjålne tilgangsopplysninger, botlignende hastighet, geografisk umulige forflytninger, nye enheter, anonymiserende nettverk og engangsadresser samt dine egne regler og tillatelses- og blokkeringslister. Hver avgjørelse loggføres. Når du aktiverer håndheving, blokkerer Radar tilgang eller krever en andre faktor. Se gjennom avgjørelsene her før du aktiverer håndheving, og når noen melder at de ikke kan logge inn.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar vurderer hver innlogging og registrering: forsøk med stjålne tilgangsopplysninger, botlignende hastighet, geografisk umulige forflytninger, nye enheter, anonymiserende nettverk og engangsadresser samt dine egne regler og lister. Begrunnelsen for avgjørelsene loggføres.',
    'refuse_passwords_found_in_known_data_breaches_checked_a_db4c6959' => 'Avvise passord som finnes i kjente datalekkasjer. Kontrollen skjer mot Have I Been Pwned uten at passordet noen gang sendes. Hvis tjenesten ikke kan nås, tillates registreringen i stedet for å blokkeres.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Registrerer apper som godtar dette miljøet som SAML-identitetsleverandør. Brukerne logger da inn med kontoene de allerede har her. Knytt hver app til organisasjonen den tilhører, slik at bare organisasjonens medlemmer får logge inn. Uten tilknytning er den åpen for alle i miljøet. Dette er den utgående retningen. Bruk Enterprise SSO under Autentisering for innlogging med en bedriftskonto hos en annen leverandør.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Forespørsler vises her automatisk når en app eller agent trenger godkjenning for å handle på dine vegne. Du trenger ikke gjøre noe før det. Avvis forespørsler du ikke selv har startet.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Forespørsler fra agenter som vil handle på vegne av en bruker, vises her når de kommer inn. Hver bruker godkjenner sine egne forespørsler. På denne siden kan du avvise forespørsler som ser ut som misbruk.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Nå logger personer inn med tilgangsopplysninger som lagres her. Koble til leverandøren din, så kan de bruke bedriftskontoen de allerede har. Når du deaktiverer kontoen hos leverandøren, mister de umiddelbart tilgangen her.',
    'scopes_sign_out_uris_token_settings_and_the_roles_manif_c736e69a' => 'Tilgangsområder, utloggings-URI-er, tokeninnstillinger og URL-en til rollemanifestet kopieres uendret. Hemmeligheter, nøkler og appens brukere kopieres ikke. De tilhører miljøet der de ble opprettet.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Se appen akkurat som en av brukerne: Du logger inn som personen av en oppgitt grunn og i maksimalt én time. Appen får vite hvem du egentlig er, og får ingen mulighet til å holde økten aktiv. Organisasjonens revisjonslogg registrerer hvem som gjorde det og hvorfor.',
    'send_this_single_use_link_to_whoever_configures_your_id_e8056999' => 'Send engangslenken til den som konfigurerer identitetsleverandøren din. Den utløper snart og fungerer uten en konto. Kopier den nå; den vises bare én gang.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Send engangslenken til den som administrerer organisasjonens identitetsleverandør, hvis personen ikke allerede har fått den på e-post. Den fungerer uten en konto til den utløper. Kopier den nå; den vises bare én gang.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Tilbyr miljøets identitetsendepunkter på et domene du eier, for eksempel login.example.com, i stedet for vårt. Du bekrefter eierskapet med en DNS-TXT-post. Sett dette opp hvis brukerne bare skal se din egen adresse når de logger inn.',
    'set_this_as_the_role_s_trust_policy_iam_roles_trust_rel_d432cbe5' => 'Angi dette som rollens tillitspolicy (IAM › Roles › Trust relationships). Plattformen kan bare overta rollen når den oppgir strømmens eksterne ID. Dermed kan ingen andre på plattformen rette en strøm mot din rolle.',
    'sign_ins_and_requests_that_cbox_id_scored_as_risky_enou_b09e917e' => 'Innlogginger og forespørsler Cbox ID har vurdert som risikable nok til å markeres, med de nyeste først, risikoscore og begrunnelse. Se her etter en økning i mislykkede innlogginger eller når noen melder om en innlogging de ikke har gjort.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Innlogginger, utstedte tokener, nye brukere og aktivering av tofaktorautentisering, dag for dag de siste 30 dagene, med mindre installasjonen bruker en annen periode. Siden forblir tom til den som drifter installasjonen, har konfigurert lagring for analysedata.',
    'snapshots_every_admin_support_role_each_role_held_acros_351f6f6d' => 'Tar et øyeblikksbilde av alle administrator- og støtteroller i hele miljøet som oppføringer som skal bekreftes eller tilbakekalles. En tilbakekalling fjerner rollen i alle organisasjoner samtidig.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Programvare som arbeider i dette miljøet med en administrasjonsnøkkel, for eksempel Claude Code, Cursor, en intern bot eller din egen backend. Hver får bare tilgangsområdene du har tildelt, og venter på godkjenning for handlingene du har valgt.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Enkelte roller må aldri tildeles samme person. Den som oppretter en betaling, bør ikke også godkjenne den. Angi disse rolleparene her. Cbox ID blokkerer nye tildelinger som bryter regelen, og viser hvem som allerede har begge rollene.',
    'splunk_elastic_graylog_cef_and_generic_json_are_http_co_8d405816' => 'Splunk, Elastic, Graylog, CEF og Generic JSON er HTTP-mottakere som du oppgir en URL for. Datadog, Amazon S3 og Google Cloud Storage har egne innstillinger.',
    'start_from_the_documents_in_folders_example_owners_edit_ca2a0af5' => 'Start med eksemplet med dokumenter i mapper: eiere, redigerere og lesere, der mappens tilgangsrettigheter arves av alt innhold. Tupler og tilgangskontroller krever et skjema først.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Funksjonsbrytere appene spør etter for én person i én organisasjon. Aktiver en funksjon for bestemte brukere, organisasjoner eller en andel av alle personer. Alle apper får samme svar, i tokenet eller gjennom API-et.',
    'the_address_tokens_for_this_api_name_as_their_audience_cdea85aa' => 'Adressen tokener for dette API-et angir som mottaker, og som API-et kontrollerer. Den kan ikke endres senere, fordi allerede utstedte tokener inneholder verdien.',
    'the_agent_is_refused_and_cannot_act_on_this_person_s_be_e1cd49d2' => 'Agentens forespørsel avvises, og agenten kan ikke handle på personens vegne. Avslaget registreres i revisjonsloggen og kan ikke angres. Agenten må sende en ny forespørsel.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Revisjonshendelsene appen sender for hver organisasjon den betjener: hvem som gjorde hva i produktet og når. De lagres per organisasjon i en hashkjede og vises til organisasjonens egne administratorer. Bruk dette når en organisasjon ber om en revisjonslogg for kontoen sin. Definer skjemaer for å holde hendelsene ensartede.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Revisjonshendelsene appen sender for alle organisasjoner den betjener, med de nyeste først. Hver organisasjons hendelser danner en egen hashkjede.',
    'the_audit_trail_lives_here_and_your_security_team_s_too_621820fa' => 'Revisjonsloggen ligger her, mens sikkerhetsteamets verktøy ligger et annet sted. En strøm sender hver nye oppføring direkte til verktøyene, slik at en undersøkelse ikke må begynne med en forespørsel om CSV-eksport.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'Knappen forsvinner fra organisasjonens innloggingsside. Miljøets egen leverandør overtar ikke plassen. Tilgangsopplysningene beholdes, slik at du kan slå på tilkoblingen igjen.',
    'the_ceiling_on_this_app_s_access_narrowing_it_takes_eff_5f2865bc' => 'Den øvre grensen for appens tilgang. En begrensning gjelder fra neste token. Hvis en enhet eller agent ber om et tilgangsområde du fjerner, blir forespørselen avvist i stedet for at den får mindre tilgang uten beskjed.',
    'the_destination_refused_the_settings_a_missing_bucket_a_27207d67' => 'Mottakeren avviste innstillingene, for eksempel på grunn av en manglende bucket eller feil region eller sted. Ingenting leveres før innstillingene er rettet. Oppføringene blir liggende og vente; de forkastes ikke.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'Organisasjonens e-postdomener, hvert bekreftet med en DNS-TXT-post. Når et domene er bekreftet, kan du aktivere obligatorisk videresending, slik at alle med en adresse på domenet sendes til organisasjonens SSO i stedet for passordinnlogging. Bekreft derfor alle domenene brukerne har adresser på, før du baserer deg på SSO.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per__a0955137' => 'Nøklene din egen kode bruker mot Cbox ID, med én fane per type. En hemmelig administrasjonsnøkkel lar din backend administrere organisasjoner, medlemmer, invitasjoner, roller og apper i ett miljø. En arbeidsområdenøkkel kaller arbeidsområdets API med en innebygd rolle. En publiserbar nøkkel brukes i en nettleserapp og fungerer bare fra tillatte origins. Hemmelige nøkler og arbeidsområdenøkler vises bare én gang. Kopier dem når de opprettes, og tilbakekall dem umiddelbart hvis de lekker.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'Den motsatte retningen: Cbox ID sender brukerne til bedriftens andre SaaS-produkter gjennom SCIM-endepunktene deres. Du håndterer opprettelse og avslutning av brukertilgang på ett sted i stedet for i et eget administrasjonspanel hos hver leverandør.',
    'the_name_of_your_organization_which_your_projects_envir_fde906b5' => 'Navnet på arbeidsområdet som prosjektene, miljøene og teamet tilhører, og som vises i hele konsollen. Hvis arbeidsområdet slettes, stenges alle de tilhørende innloggingsmiljøene. Derfor gjøres dette gjennom en forespørsel til kundestøtte, ikke en knapp.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Passordregler, kontolåsing og krav om tofaktorautentisering og SSO ved hver innlogging. For hele miljøet styres også om passkeys og innloggingslenker tilbys, og hvor lenge økter varer. Miljøet angir grunnregler som alle organisasjoner arver. Organisasjoner kan skjerpe passord- og tofaktorreglene, men aldri svekke dem.',
    'the_services_of_yours_that_receive_access_tokens_and_th_8f7e35e1' => 'Tjenestene dine som mottar tilgangstokener, og tilgangsområdene hver tjeneste eier. Du bestemmer hvem som får tilgangsområdene til et registrert API. Ingen kan bare skrive dem inn på en app for å få tilgang til API-et.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Hele miljøet tilbyr leverandøren på alle innloggingssider. Velg en organisasjon for å sette opp en egen leverandør i stedet. Den erstatter da miljøets leverandør på organisasjonens innloggingsside.',
    'the_organization_s_own_keys_for_the_organization_api_li_86017b30' => 'Arbeidsområdets egne nøkler til arbeidsområdets API: list prosjekter og miljøer, opprett miljøer, og list og inviter teammedlemmer. Hver nøkkel har en innebygd rolle.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Personens økter og tokener tilbakekalles. Passkeys, andre faktorer, medlemskap, rolletildelinger, API-tokener, hemmeligheter i hvelvet, enheter og alle lagrede kopier av personopplysningene slettes. Kontoen beholdes bare som en pseudonymisert, deaktivert oppføring. Apper som synkroniserer personer herfra, får beskjed om å slette personen. Revisjonsloggen beholder den ugjennomsiktige ID-en, ikke navn eller e-postadresse.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Disse hookene kjører under en operasjon, ikke etterpå, og svaret påvirker resultatet. Endepunktet ditt kan legge til informasjon i et token eller avvise en innlogging helt. De griper direkte inn i prosessen, så et tregt eller defekt endepunkt påvirker personen som prøver å logge inn.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Personen mister umiddelbart tilgang til alle plattformsider i installasjonen. Eksisterende økter slutter å fungere ved neste forespørsel. Du kan aktivere personen igjen her.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Dette kan ikke angres. Tilgangsopplysninger, medlemskap og personopplysninger slettes, og kontoen pseudonymiseres. Hvis personen er eneste eier av en organisasjon, må eierskapet overføres først.',
    'this_deployment_has_no_turnstile_keys_cbox_id_turnstile_9ceda61f' => 'Installasjonen mangler Turnstile-nøkler (CBOX_ID_TURNSTILE_SITE_KEY), så ingen Turnstile-kontroll kan aktiveres. Ved en markert registrering bekreftes e-postadressen i stedet.',
    'this_endpoint_belongs_to_the_environment_and_fires_for_2bbbb6fd' => 'Endepunktet tilhører miljøet og kjøres for hver organisasjon i det. Det vises her fordi det kjøres ved innloggingene dine. Det administreres av operatøren.',
    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Dette miljøet tilbyr en MCP-server ved siden av REST-API-et. Koble til en agent med en administrasjonsnøkkel, så kan den utføre nøyaktig det nøkkelens tilgangsområder tillater, med de samme kontrollene, godkjenningene og revisjonsloggen som konsollen.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Dette miljøet tilbyr en MCP-server, standardgrensesnittet for AI-assistenters verktøykall, ved siden av REST-API-et. Legg inn adressen og en administrasjonsnøkkel i Claude Code, Cursor eller en annen MCP-klient. Agenten kan utføre nøyaktig det nøkkelens tilgangsområder tillater, med de samme kontrollene og revisjonsloggen som konsollen.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Brukeren kan ikke lenger logge inn i noen app i miljøet. Eksisterende økter slutter å fungere ved neste forespørsel. Opplysningene beholdes, og du kan aktivere brukeren igjen når som helst.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Brukeren eier eller administrerer en organisasjon. Slike kontoer kan ikke overtas for brukerstøtte, fordi dette kunne gitt varig kontroll over organisasjonen til den som overtar identiteten.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'I dag legges personer til og fjernes her manuelt. Koble til bedriftens eksisterende katalog, så håndteres begge deler automatisk, også fjerningene som ellers lett blir glemt.',
    'until_an_api_is_registered_a_scope_is_just_text_on_an_a_db7d3254' => 'Før et API er registrert, er et tilgangsområde bare tekst på en app. Alle som kan redigere appen, kan tildele den hvilke tilgangsområder som helst. Registrer API-ene appene kaller, slik at tilgangsområdene får en eier.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Bekreftede domener leder personer til din egen identitetsleverandør. Funksjonen inngår i Enterprise-abonnementet. Kontakt kundeansvarlig for å aktivere den for organisasjonen.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Når du bekrefter et domene du eier, for eksempel acme.com, kan Cbox ID gjenkjenne brukerne på e-postadressen og sende dem rett til leverandøren. Da trenger ingen å velge riktig innloggingsknapp.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Webhooks, utloggingsmeldinger til tilkoblede apper, henting av rolleoppdateringer og e-post i kø behandles i bakgrunnen av køarbeidere, uten at personen må vente. Hvis ingen køarbeider kjører, behandles ingenting av dette, selv om resten av konsollen ser normal ut. På denne siden ser du problemet.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Handlinger agentene i miljøet venter på godkjenning for. Hvis nøkkelen krever godkjenning, stopper agenten og spør personen som opprettet nøkkelen. Personen kan svare på telefonen eller her. Den som administrerer miljøet, kan avvise mistenkelige forespørsler. Nedenfor vises apper som ber om å handle som en bruker; disse forespørslene godkjenner hver bruker selv.',
    'what_an_app_may_be_allowed_to_do_at_this_api_your_own_a_94f7133a' => 'Hva en app kan få gjøre i dette API-et. Dine egne apper kan få alle tilgangsområdene. Apper registrert av en organisasjon kan bare få dem som er merket for organisasjoner.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Handlinger programvaren i miljøet venter på godkjenning for. En agent med en nøkkel som krever godkjenning, stopper og spør personen som opprettet nøkkelen. Svar her eller på telefonen.',
    'what_your_code_asks_for_and_what_the_feature_flags_clai_440d8ca1' => 'Nøkkelen koden din spør etter, og som feltet feature_flags inneholder. Små bokstaver og sifre, med - _ eller . mellom dem. Nøkkelen kan ikke endres senere.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Når en app eller AI-agent trenger godkjenning for å handle på dine vegne, kan den ikke alltid spørre på skjermen foran deg. Derfor vises forespørselen her. Godkjenn bare forespørsler du selv har startet, og kontroller at koden samsvarer med koden på enheten som spør.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Når ALLE vilkårene er oppfylt, utfører Radar regelens handling og vurderer ingen etterfølgende regler. Disse reglene vurderes etter tillatelses- og blokkeringslistene og før de innebygde reglene.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'Dit Cbox ID sender personer etter utlogging fra appen. URI-en appen ber om, må stå her helt nøyaktig, inkludert eventuell avsluttende skråstrek. Ellers blir personen på Cbox IDs utloggingsside. La feltet stå tomt hvis appen aldri ber om å sende brukeren tilbake.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Hvor du er innlogget, hva som kan handle på dine vegne, og hva som har skjedd med kontoen din. Hvis du ser noe du ikke kjenner igjen, logger du ut den økten og endrer passordet.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Under overgangen fra et annet system kan appen oppgi det gamle innloggingsendepunktet i manifestet sammen med rollene. Det vises her for godkjenning før det brukes.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Under overgangen fra et annet system kan en app be om at e-postadresse og passord for personer som ennå ikke finnes i Cbox ID, kontrolleres mot det gamle innloggingsendepunktet. Test endepunktet før du godkjenner det. Personer det godtar, opprettes her og sendes aldri dit igjen. Hvis endepunktet er nede, kan de som ennå ikke er flyttet, ikke logge inn.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Uten roller får alle som kan logge inn, rettighetene appen gir vanlige brukere. Med roller angir du én gang hvem som for eksempel er redigerere, og hvem som jobber med brukerstøtte. Alle tilkoblede apper kan følge denne inndelingen.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Opprett en regel som tillater, krever ekstra verifisering eller blokkerer ut fra det du vet om brukerne. Krev for eksempel ekstra verifisering ved innlogging fra land dere ikke opererer i, eller unnta kontornettverket fra reglene for innloggingshyppighet.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Du opptrer som personen, i personens økt og med personens tilgang. Økten er begrenset til 30 minutter og er skrivebeskyttet der konsollen kan håndheve det. Hver forespørsel registreres under ditt navn.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Du mister tilgangen umiddelbart. Som eier kan du bare forlate organisasjonen når noen andre eier den. Overfør eierskapet først, eller slett organisasjonen under Innstillinger.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Appens egen tilgangsmodell: ressurstyper som dokumenter og mapper, relasjoner som eier, redigerer og leser, og hvordan de arves. Den som kan lese en mappe, kan for eksempel lese alle dokumentene i den. Appen lagrer hvem som har hvilken relasjon til hvilken ressurs, og spør ved hver forespørsel: «kan denne brukeren redigere dokumentet?». Skjemaet avgjør svaret.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'Appens egen tilgangsmodell: ressurstyper, relasjonene for hver type og hvordan de arves. Appen skriver tupler — hvem som har hvilken relasjon til hva — og kontrollerer tillatelser ved hver forespørsel.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Appen sender disse hendelsene med ett kall per gruppe. Hver hendelse angir organisasjonen der den oppstod. De vises her og for organisasjonens egne administratorer etter hvert som de kommer inn.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'Miljøets standardprofil: utseendet, logoen og faviconet for den driftede innloggingen samt navnet og avsenderen brukerne ser. Alle organisasjoner arver profilen med mindre de angir sin egen.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Identitetsleverandøren oppretter, oppdaterer og deaktiverer personer her automatisk via standarden SCIM. Når noen begynner eller slutter i HR-systemet, når endringen appene i løpet av sekunder, uten saker eller gjenglemte kontoer — særlig viktig når noen slutter.',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Dine egne innloggingsmetoder og aktive økter. En passnøkkel gir sterkest beskyttelse og er raskest å bruke: enheten låser den opp med fingeravtrykk eller ansiktsgjenkjenning, og det finnes ikke noe passord som kan stjeles gjennom nettfisking.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Mottakeren beholder den samme hemmeligheten. En heksadesimal hemmelighet med 64 tegn blir whsec_ etterfulgt av base64-kodingen av strengen — "whsec_" + base64(secret). En hemmelighet som allerede begynner med whsec_, brukes uendret.',
    '_groups_part1_39d243e0' => '{
  "groups": [":part1"]
}',
    '_part1_things_worth_doing_roughly_in_this_order_each_on_b3e154c4' => ':part1 oppgaver som bør gjøres, omtrent i denne rekkefølgen. Hver oppgave merkes automatisk som fullført når den faktisk er ferdig. Du trenger ikke krysse av noe manuelt.',
    '_sub_the_person_s_id_org_the_organization_they_are_acti_2e2ddc7f' => '{
  "sub": "personens ID",
  "org": "organisasjonen personen handler på vegne av",
  "roles": [":part1"],
  "permissions": [:part2]
}',
    'an_api_key_organization_settings_api_keys_not_an_applic_916c023d' => 'En API-nøkkel (Organisasjonsinnstillinger › API-nøkler), ikke en applikasjonsnøkkel. Lagret kryptert og aldri vist igjen.:part1',
    'how_people_sign_in_to_part1_these_start_as_your_environ_133e7090' => 'Hvordan folk logger på :part1. Disse starter som miljøets standardinnstillinger; alt du endrer her kan bare gjøre dem strengere.',
    'its_members_are_signed_out_and_all_part1_it_owns_stop_s_80b419eb' => 'Medlemmene logges ut og alle :part1 den eier slutter å levere autentisering ved neste forespørsel. Du kan aktivere den på nytt her.',
    'its_part1_are_signed_out_and_all_part2_it_owns_stop_ser_c1a0c179' => 'Dens :part1 er logget ut og alle :part2 den eier slutter å levere autentisering ved neste forespørsel. Du kan aktivere den på nytt her.',
    'its_part1_can_no_longer_sign_in_to_this_organization_an_9a6e499c' => 'Organisasjonens :part1 kan ikke lenger logge inn i den, og apper som bruker den til autentisering, kan ikke lenger autentisere dem. Underorganisasjoner suspenderes ikke samtidig. Du kan aktivere organisasjonen igjen her.',
    'minutes_at_most_part1_empty_uses_the_deployment_s_part2_2c261db9' => 'Minutter, på det meste :part1. Empty bruker distribusjonens :part2. Hvis du forkorter den, avsluttes også lengre økter som allerede kjøres.',
    'only_if_your_app_needs_more_from_part1_than_sign_in_doe_fc539001' => 'Bare hvis appen din trenger mer fra :part1 enn pålogging gjør – atskilt med mellomrom. Innloggings egne omfang etterspørres alltid.',
    'paste_the_whole_json_key_file_of_a_service_account_gran_6f4e93cd' => 'Lim inn hele JSON nøkkelfilen til en tjenestekonto gitt roles/storage.objectCreator på bøtte. Lagret kryptert og aldri vist igjen.:part1',
    'sandbox_environments_allow_localhost_urls_and_never_sen_299fef2d' => 'Sandbox-miljøer tillater lokale verts-URLer og sender aldri ekte e-post. :part1 gjenstår på dette prosjektets plan.',
    'sign_in_to_one_of_your_apps_as_part1_to_see_what_they_s_1c96b645' => 'Logg på en av appene dine som :part1 for å se hva de ser. Appen blir fortalt at det er deg, og organisasjonens revisjonslogg registrerer hvem, når og hvorfor.',
    'the_app_whose_declared_roles_and_permissions_tokens_for_f9092feb' => 'Appen hvis erklærte roller og tillatelser for denne API har. Kun apper som eies av :part1 kan velges.',
    'what_part1_s_sign_in_page_offers_providers_from_the_env_efc01f8e' => 'Tilbudet på innloggingssiden til :part1. Leverandører arves fra miljøet; organisasjonen kan slå av en leverandør eller sette opp sin egen i stedet.',
    'when_an_agent_s_key_needs_approval_for_an_action_the_re_56c5e366' => 'Når en agents nøkkel trenger godkjenning for en handling, vises forespørselen her og på telefonen til personen som opprettet nøkkelen. Den venter opptil :part1.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'Hvilke måter i :part1 tilbyr i tillegg til et passord, og hvor lenge en pålogging varer. Disse er de samme for hver organisasjon i den.',
    '_part1_the_part2_claim_is_a_different_thing_it_is_what_c15748b6' => ':part1 Feltet :part2 er noe annet: Det angir hva :part3 :part4 fikk lov til å be om, ikke hva denne :part5 har lov til å gjøre.',
    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 De brukes ikke til å logge inn i denne konsollen. Administratorer logger inn gjennom Cbox ID på :part2 med innloggingsmetodene som er tilgjengelige der.',
    '_part1_tick_the_part2_part3_scope_when_you_register_the_ef0603eb' => ':part1 Merk av for :part2 :part3 når du registrerer appen. ID-tokenet inneholder da de samme rollenavnene i feltet :part4, som Kubernetes, Grafana og Vault ser etter. Du trenger ikke opprette noe mer.',
    '_part1_you_are_impersonating_part2_part3_for_support_ev_aaad4d39' => ':part1 Du opptrer som :part2 :part3 for å gi brukerstøtte. Alt du gjør, loggføres. :part4 :part5 :part6',
    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'En administrasjonsnøkkel virker bare i sitt eget miljø. Eksporter appens oppsett (GET /apps/{id}/blueprint), og registrer det med nøkkelen til det andre miljøet (POST /apps med `blueprint`).',
    'a_management_key_for_one_agent_it_can_do_only_what_its_e35f0a5f' => 'En administrasjonsnøkkel for én agent. Den kan bare gjøre det tilgangsomfangene tillater, og handlingene du velger, venter på godkjenning fra deg på telefonen eller på :part1.',
    'a_page_on_part1_leave_empty_to_land_in_the_console_with_1e303bfc' => 'En side på :part1. La feltet stå tomt for å åpne konsollen, med :part2 angitt i invitasjonen.',
    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => 'Et :part1 er identitetsleverandøren til ett produkt. Det inneholder isolerte :part2 :part3 for produksjon og testing, hver med egne brukere, nøkler og innlogging, og faktureres etter sin egen abonnementsplan.',
    'a_permission_is_what_a_part1_may_do_once_signed_in_what_d4afab64' => 'En rettighet angir hva en :part1 kan gjøre etter innlogging. Hva en :part2 kan be om, er et tilgangsomfang som angis når du registrerer den under :part3 :part4.',
    'an_organization_key_reaches_the_organization_itself_pro_0257779c' => 'En arbeidsområdenøkkel gir tilgang til selve arbeidsområdet: prosjekter, miljøer, teamet og nøkler. Den gir ikke tilgang til innholdet i et miljø. Opprett en under :part1 :part2 :part3 på plattformnivå.',
    'access_tokens_for_this_app_name_part1_as_their_audience_0da966a0' => 'Tilgangstokener for denne appen angir :part1 som mottaker :part2. Dette API-et skal bare godta et token når det er angitt som mottaker.',
    'access_tokens_for_this_app_name_this_environment_s_issu_13b4d3ef' => 'Tilgangstokener for denne appen angir miljøets utsteder, :part1 :part2, som mottaker. Dette endres når appen har et tilgangsomfang fra et av de registrerte API-ene dine.',
    'add_a_txt_record_at_part1_part2_with_the_value_below_th_455edc17' => 'Legg til en TXT-post på :part1 :part2 med verdien nedenfor, og klikk på Bekreft. Det kan ta noen minutter før DNS-endringer blir synlige.',
    'an_app_registers_its_catalog_over_the_sdk_part1_part2_y_384ea703' => 'En app registrerer katalogen sin gjennom SDK-et. :part1 :part2 Du kan opprette rollen nå og sette den sammen når nøklene er tilgjengelige.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Apper som stoler på dette miljøet som sin SAML-identitetsleverandør. Bruk :part1 :part2 for å la brukere logge inn med en konto de allerede har et annet sted.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'Godkjenninger gjelder handlingene i administrasjons-API-et. Disse tilgangsomfangene brukes av endepunkter som ennå ikke er handlinger, så de kjøres uten å spørre: :part1 :part2.',
    'apps_send_people_to_sign_up_with_part1_and_ask_a_signed_e3725846' => 'Apper sender brukere til registrering med :part1 og ber innloggede brukere opprette en organisasjon med :part2. Begge deler tilbys bare når dette er slått på.',
    'asked_exactly_as_your_app_asks_it_part1_through_every_i_42253b49' => 'Spørsmålet stilles akkurat som i appen din (:part1), gjennom alle arverelasjonene skjemaet definerer.',
    'auth_settings_differ' => ':count innstilling avviker fra miljøet ditt.|:count innstillinger avviker fra miljøet ditt.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_df000287' => 'Koble til én gang på plattformnivå i stedet for én gang per miljø. Innlogget som deg får den tilgang til arbeidsområdet ditt, alle miljøene der du er administrator, og din egen konto. Et miljøverktøy tar argumentet :part1 :part2, og REST-API-et tar headeren :part3, som angir hvor handlingen skal utføres. Den kan gjøre det du kan innenfor det du tillater, og alle kritiske handlinger venter på godkjenning fra deg på enheten din.',
    'each_new_account_creates_its_own_organization_and_owns_3528fda3' => 'Hver ny konto oppretter og eier sin egen organisasjon. Apper kan også be innloggede brukere opprette en med :part1 :part2.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Hver organisasjon gir dem én :part1, som angir hva de kan administrere der, og et valgfritt antall :part2, som angir hva de kan gjøre i appene.',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'Miljøet «:part1» er opprettet. Legg til :part2 i miljøets domeneinnstillinger for å bekrefte det via DNS. Et ubekreftet domene kan ikke være miljøets utsteder.',
    'environments_nest_under_a_project_and_a_project_under_a_a7f5aa8e' => 'Miljøer tilhører et prosjekt, og prosjekter tilhører et :part1 :part2 :part3. Start der for å se alt som tilhører ett arbeidsområde. To typer rader har aldri et arbeidsområde: :part4 er miljøet denne installasjonen kjører i, der operatører og arbeidsområdets egne brukere finnes. Et :part5 :part6 miljø har ikke noe prosjekt, så det faktureres ikke og er ikke tilgjengelig fra noe arbeidsområde. Ingen av delene er en feil som skal rettes her, og denne siden flytter dem ikke.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'Alle metodene for innlogging i :part1, om de er slått på, og hvor de endres. Organisasjoner kan gjøre kravene strengere: :part2 :part3.',
    'every_organization_environment_and_operator_on_part1_a__f425b7e6' => 'Alle arbeidsområder, miljøer og operatører på :part1. Suspensjon, nye miljøer og operatørendringer her gjelder på tvers av dem alle.',
    'feature_flag_part1_created_it_is_off_for_everyone_until_32603be3' => 'Funksjonsflagget «:part1» er opprettet. Det er av for alle til en regel nedenfor eller standardverdien slår det på.',
    'framework_3cf574caed49' => 'Tilgangsomfangene :value1 tilhører et registrert API denne klienten ikke kan få tilgang til. En organisasjonseid klient kan ha tilgangsomfang fra organisasjonens egne API-er og tilgangsomfang fra miljøeide API-er som organisasjoner kan be om.',
    'framework_43fd205dea6a' => 'Tilgangsomfanget [:key] tilhører allerede et annet API i dette miljøet. Nøkler for tilgangsomfang er unike per miljø, fordi en tokenforespørsel angir tilgangsomfanget bare med nøkkelen.',
    'framework_47867973811e' => 'Katalogsynkronisering med :provider mislyktes: :request ble begrenset på grunn av for mange forespørsler (HTTP :status) etter :attempt forsøk.',
    'framework_5eb368b0fb37' => 'Workday: Rapportens URL må være nettjenesteadressen til rapporten: …/ccx/service/customreport2/{tenant}/{owner}/{report}.',
    'framework_632573ec7b49' => 'Appen [:clientId] må ha samme eier som API-et den håndhever tilgang for. En kobling ville ellers lagt én eiers roller og rettigheter inn i en annen eiers tokener.',
    'framework_87da9891b0ad' => 'Katalogsynkronisering med :provider mislyktes: :request var utilgjengelig (HTTP :status) etter :attempt forsøk.',
    'framework_98eb4683e38b' => 'Katalogsynkronisering med :provider mislyktes: :request mislyktes (HTTP :status): ikke funnet. Kontroller kontoen, underdomenet eller rapportadressen.',
    'framework_a934fd6a0c26' => '[:origin] bruker http. Nøkkelen og alt siden gjør med den, ville derfor blitt sendt ukryptert over nettverket. Bruk https, eller en lokal adresse som http://localhost:3000 under utvikling.',
    'framework_b63785ee57fb' => 'Katalogsynkronisering med :provider mislyktes: :request mislyktes (HTTP :status): påloggingsopplysningene mangler rettighet til å lese ansatte.',
    'framework_e5ca82ab9dff' => 'Katalogsynkronisering med :provider mislyktes: :request mislyktes (HTTP :status): påloggingsopplysningene ble avvist.',
    'framework_fc1964a8e8c4' => 'Dette er den siste aktive hemmeligheten til klienten [:clientId]. Roter hemmeligheten for å erstatte den. Tilbakekalling ville gjort at klienten ikke lenger kunne autentisere seg.',
    'if_that_endpoint_is_part1_people_who_have_not_migrated_18fc0415' => 'Hvis endepunktet er :part1, kan brukere som ikke er migrert, ikke logge inn. Brukere som allerede er flyttet, påvirkes ikke.',
    'in_the_order_people_see_them_turning_one_of_the_environ_390888a5' => 'I rekkefølgen brukerne ser dem. Når du slår av en av miljøets metoder her, fjernes bare knappen fra denne siden. Brukere kan fortsatt logge inn med metoden andre steder. Krev SSO på :part1 :part2 for å gjøre identitetsleverandøren din til eneste innloggingsmetode.',
    'keys_start_with_it_so_a_key_found_in_a_log_names_this_a_8a69e3c2' => 'Nøkler begynner med dette prefikset, slik at en nøkkel i en logg kan knyttes til appen: :part1 :part2. 2–16 små bokstaver eller sifre, etterfulgt av :part3 eller :part4 :part5, unikt i dette miljøet. Et angitt prefiks aktiverer nøkler. Hvis du fjerner det, stoppes nye nøkler; eksisterende nøkler fungerer til de tilbakekalles.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'List funksjonsflagg med målgruppereglene deres, og evaluer hvert flagg for en bruker i en organisasjon. Dette er det appens backend ber om når den ikke har et token.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'List katalogene (SCIM, Google Workspace, Microsoft Entra) som synkroniserer inn personer, gruppene deres og synkroniseringsfeil. Bearer-tokener og leverandørenes tilgangsopplysninger utleveres aldri.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'List SAML- og OIDC-tilkoblingene organisasjoner bruker til innlogging, samt e-postdomenene som leder personer til dem. Sertifikater, klienthemmeligheter og signeringsnøkler utleveres aldri.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'List tredjepartsleverandører personer kan koble kontoene sine til, hvilke apper som kan få midlertidig tilgang til disse tokenene, og hvem som har koblet seg til. Klienthemmeligheter og tokener utleveres aldri.',
    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Opprett og trekk tilbake engangslenker til administratorportalen. Med lenken kan organisasjonens IT-administrator sette opp SSO, domener eller katalogsynkronisering uten en konto. En ny lenke vises bare én gang.',
    'no_roles_to_map_onto_yet_define_one_under_part1_part2_o_9b9aba76' => 'Ingen roller å tilordne ennå. Definer en under :part1 :part2, eller la en app deklarere sine egne.',
    'nobody_in_this_organization_has_created_a_key_for_one_o_d0240315' => 'Ingen i denne organisasjonen har opprettet en nøkkel for noen av appene. Brukerne oppretter egne nøkler under Min konto for en app som har aktivert API-nøkler for medlemmer i innstillingene sine: :part1.',
    'nobody_is_signed_in_to_an_app_as_one_of_its_people_star_a41ae388' => 'Ingen er logget inn i en app som en av brukerne. Start en slik økt fra en brukers side under :part1 :part2.',
    'only_the_console_can_give_an_app_part1_not_a_management_e9037160' => 'Bare konsollen kan gi en app :part1. En administrasjonsnøkkel eller en agent som handler på dine vegne, kan ikke gjøre det. Gi tilgangen på appens side for tilgangsomfang i konsollen.',
    'only_what_you_can_do_in_part1_yourself_is_offered_if_yo_54637548' => 'Bare handlinger du selv kan utføre i :part1, tilbys. Hvis du senere mister en rettighet, mister nøkkelen den også.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Legger nøklene til funksjonsflaggene som er aktivert for personen i organisasjonen vedkommende logget inn i, i feltet `feature_flags` i tilgangstokenet, ID-tokenet og UserInfo.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Legger personens ROLLER i ID-tokenet under navnet `groups`, som Kubernetes, Grafana, Vault og mange eldre SaaS-apper forventer. Det finnes ikke noe objekt kalt gruppe i denne konsollen. Opprett en rolle med navnet appen forventer, så blir den tatt med der.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Lese Radars modus, innebygde og egne regler, tillatelses- og blokkeringslister samt avgjørelsesoversikten: hvorfor en innlogging eller registrering ble tillatt, krevde ekstra verifisering eller ble blokkert. IP- og e-postadresser fra avgjørelser utleveres aldri.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'Lese revisjonshendelser appen har sendt og eksporter av dem, verifisere en organisasjons hendelseskjede og lese tilhørende skjemaer og oppbevaringsregler.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Lese autorisasjonsskjemaet og tuplene, samt utføre tilgangskontroller og listeforespørsler, for eksempel «kan denne brukeren redigere dokumentet?» eller «hvilke dokumenter kan personen se?». Bare rettighetene appens backend trenger for å håndheve tilgang.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Erstatt autorisasjonsskjemaet: ressurstypene og hvordan hver relasjon avgjøres. Dette endrer svaret på alle tilgangskontroller i miljøet med én gang.',
    'roles_held_across_the_whole_environment_in_every_organi_eb64cef7' => 'Roller som gjelder i hele miljøet, i alle organisasjoner og også for brukere som ikke tilhører noen organisasjon. Organisasjonene ser aldri disse. :part1 :part2',
    'sandbox_environment_for_testing_only_this_is_part1_your_4efdd306' => 'Testmiljø, bare for testing. Dette er :part1 produksjonsinnloggingen din, og det sendes ingen ekte e-poster.',
    'scope_part1_removed_apps_that_held_it_keep_it_as_a_type_7572a80d' => 'Tilgangsomfanget «:part1» er fjernet. Apper som hadde det, beholder det som et egendefinert tilgangsomfang som ikke lenger gir tilgang til dette API-et.',
    'showing_the_first_part1_search_to_reach_the_rest_anythi_57d8cba9' => 'Viser de første :part1. Søk for å finne resten. Alt du allerede har merket av, blir stående på listen.',
    'sms_allowed_country_count' => 'Godtas som andre faktor i :count land.|Godtas som andre faktor i :count land.',
    'someone_who_part1_is_never_sent_their_password_is_the_o_6e557319' => 'Brukere som :part1, sendes aldri videre. Passordet deres er det som er lagret i Cbox ID, og det gamle systemet har ingen innflytelse på det.',
    'someone_who_signs_in_and_is_part1_has_their_email_and_p_07a25128' => 'Når en bruker logger inn og er :part1, sendes e-postadressen og passordet til endepunktet. Hvis det godkjenner dem, opprettes brukeren her og sendes aldri videre igjen.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Lagre, roter og tilbakekall tilgangsopplysninger for eksterne tjenester, og gi eller trekk tilbake en apps rett til å bruke dem midlertidig. Dette gjelder ikke tilgangsområdene vault.manage / vault.lease i appens eget token.',
    'streamable_http_every_request_carries_part1_part2_a_man_6348600d' => 'Streamable HTTP. Hver forespørsel inneholder :part1 :part2, en administrasjonsnøkkel for dette miljøet.',
    'stuck_on_one_of_these_every_page_in_the_console_has_a_p_2aa4622e' => 'Trenger du hjelp med noe av dette? Hver side i konsollen har en :part1 :part2 :part3 ved tittelen med en kort forklaring og en lenke til hele veiledningen.',
    'suspension_is_the_only_lever_here_and_it_is_reversible__9f87c506' => 'Her kan du bare suspendere et arbeidsområde eller aktivere det igjen. Ingenting på siden sletter et arbeidsområde eller fjerner dataene permanent. Installasjonen inneholder også miljøer uten arbeidsområde: plattformens rotmiljø og eventuelle gjenværende miljøer uten tilknytning. Begge er tydelig merket under :part1 :part2.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Denne siden endrer bare suspensjonen, som kan oppheves. Å velge og åpne et miljø endrer bare konsollens visning. Ingen av miljøene endres.',
    'text_message_codes_to_part1_stop_working_their_authenti_81d0cd27' => 'SMS-koder til :part1 slutter å fungere. Autentiseringsappen, passkeys og gjenopprettingskodene påvirkes ikke. Hvis telefonnummeret var personens eneste andre faktor, er kontoen bare beskyttet av passordet til en ny faktor registreres.',
    'that_certificate_has_already_expired_part1_download_the_9adb4bed' => 'Sertifikatet er allerede utløpt (:part1). Last ned det gjeldende sertifikatet fra identitetsleverandøren din.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Dette nettleserikonet kan ikke brukes. Send selve bildet som en base64-kodet data:-URI (data:image/png;base64,…). Eksterne bilde-URL-er godtas ikke. Hver besøkende henter bildet på innloggingssiden, og en ekstern bildeserver ville dermed fått informasjon om de besøkende.',
    'that_is_a_lot_of_emails_try_again_in_part1_seconds_or_c_1e69af47' => 'Det var mange e-poster. Prøv igjen om :part1 sekunder, eller sjekk søppelpostmappen i mellomtiden.',
    'that_is_everything_on_the_list_from_here_the_console_is_d3be406f' => 'Nå er alle punktene på listen fullført. Fremover kommer du først og fremst tilbake til konsollen ved behov. To områder bør du kontrollere regelmessig: :part1 :part2 :part3 og :part4 :part5 :part6.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'Denne logoen kan ikke brukes. Send selve bildet som en base64-kodet data:-URI (data:image/png;base64,…). Eksterne bilde-URL-er godtas ikke. Hver besøkende henter bildet på innloggingssiden, og en ekstern bildeserver ville dermed fått informasjon om de besøkende.',
    'the_email_domains_your_organizations_have_claimed_a_ver_97773852' => 'E-postdomenene organisasjonene dine har gjort krav på. Et bekreftet domene sender alle med en adresse på domenet til organisasjonens tilkobling: :part1 :part2. Hvert domene bekreftes på organisasjonens side.',
    'the_platform_s_own_environment_on_part1_how_every_organ_acd123ad' => 'Plattformens eget miljø på :part1: Her logger alle arbeidsområdeeiere og operatører inn i Cbox ID, og her skjer innloggingen til alle miljøkonsoller. En endring gjelder for alle disse innloggingene.',
    'the_role_part1_cannot_be_held_in_this_organization_it_b_6fdeacd4' => 'Rollen [:part1] kan ikke tildeles i denne organisasjonen. Den tilhører en annen organisasjon eller en app denne organisasjonen ikke kan bruke.',
    'there_is_no_client_secret_to_paste_part1_expects_a_sign_574fe375' => 'Det finnes ingen klienthemmelighet å lime inn. :part1 forventer i stedet en signert assertion, som vi oppretter med nøkkelen ovenfor for hver innlogging og fornyer lenge før den utløper.',
    'there_is_no_role_to_grant_yet_define_one_on_the_part1_p_ffe056a6' => 'Det finnes ingen rolle å tildele ennå. Definer en på siden :part1 :part2 :part3, eller la en app deklarere sine egne i manifestet.',
    'these_are_the_buttons_on_part1_how_every_organization_o_ca549807' => 'Dette er knappene på :part1 som arbeidsområdeeiere og operatører bruker for å logge inn i Cbox ID og dermed i alle miljøkonsoller. Administratorene der bruker Cbox ID-kontoer. Registrer videresendings-URI-en som vises for hver leverandør, hos leverandøren. Du finner den under :part2 :part3.',
    'these_buttons_are_for_the_people_who_sign_in_to_your_ap_580f5efd' => 'Disse knappene er for brukerne som logger inn i appene dine, på innloggingssidene til :part1 :part2. :part3',
    'they_become_the_owner_of_part1_and_you_become_an_admin_09c4a8dc' => 'Vedkommende blir eier av :part1, og du blir administrator. Bare den nye eieren kan overføre eierskapet tilbake.',
    'this_app_holds_scopes_of_more_than_one_api_part1_part2_163d032f' => 'Appen har tilgangsområder for flere API-er: :part1 :part2. Et token gjelder for ett API om gangen, så appen angir ønsket API med parameteren :part3. En forespørsel om tilgangsområder for to API-er samtidig avvises.',
    'this_console_is_your_organization_its_projects_team_key_15ebbd0f' => 'Denne konsollen er arbeidsområdet ditt med prosjekter, team, nøkler og fakturering. Hvordan personer logger inn i appene dine, inkludert :part1, konfigureres for hvert miljø i miljøets egen konsoll.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Denne handlingen krever en persons godkjenning for disse tilgangsopplysningene, men ingen person er registrert for å gi den. Utfør handlingen i konsollen, eller opprett en nøkkel der slik at eieren kan godkjenne.',
    'this_deployment_only_texts_part1_so_numbers_in_part2_ca_6cb21f4d' => 'Denne installasjonen sender bare SMS til :part1. Numre i :part2 kan derfor ikke motta koder før landene er tatt med i CBOX_ID_SMS_ALLOWED_COUNTRIES.',
    'this_environment_s_issuer_discovery_and_jwks_are_served_06e9c844' => 'Miljøets utsteder, discovery og JWKS er tilgjengelige på :part1 :part2. Pek verten mot inngangspunktet ditt, og terminer TLS der.',
    'this_environment_s_own_issuer_what_an_sdk_discovers_fro_b00e706b' => 'Miljøets egen utsteder: adressen SDK-et bruker til oppdagelse, og som finnes i feltet :part1.',
    'this_person_is_the_only_owner_of_part1_organization_s_p_662dfa99' => 'Denne personen er eneste eier av :part1 organisasjon(er): :part2. Overfør eierskapet før personen slettes.',
    'typed_scopes_part1_are_unowned_they_travel_as_they_are_e061e25f' => 'Egendefinerte tilgangsomfang (:part1) har ingen eier. De sendes som de er, og aldri med et registrert API som mottaker.',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'E-posten kunne ikke sendes nå fordi installasjonen ikke får kontakt med e-postserveren. Prøv igjen senere. En administrator kan også bekrefte adressen din med `php artisan cbox-id:users:confirm-email`.',
    'we_have_sent_a_few_links_already_try_again_in_part1_sec_a84fe552' => 'Vi har allerede sendt noen lenker. Prøv igjen om :part1 sekunder, eller sjekk søppelpostmappen i mellomtiden.',
    'we_sent_a_link_to_part1_your_first_environment_your_liv_9786541d' => 'Vi sendte en lenke til :part1. Når du åpner den, opprettes det første miljøet ditt: identitetsleverandøren din i produksjon, med egen innlogging, brukere og signeringsnøkler. Deretter kommer du rett tilbake hit. Lenken er gyldig i 24 timer.',
    'which_of_its_actions_wait_for_a_person_the_agent_gets_a_e72df5dd' => 'Handlingene som venter på godkjenning. Agenten får et 202-svar med en kort kode. Du godkjenner på telefonen eller under :part1 :part2, og agenten gjentar forespørselen nøyaktig én gang.',
    'write_and_delete_relationship_tuples_who_owns_edits_or_53581cba' => 'Skrive og slette relasjonstupler: hvem som eier, redigerer eller ser hvilke ressurser i appen. Tilgangen i appen gis eller tilbakekalles straks endringen skrives.',
    'you_are_signed_in_part1_but_your_account_does_not_admin_1a2cb08a' => 'Du er innlogget :part1, men kontoen din kan ikke administrere :part2. Miljøkonsollen kan åpnes av eiere, administratorer og utviklere i arbeidsområdet miljøet tilhører.',
    'you_have_no_environment_to_open_yet_part1_part2_part3_t_3a10832d' => 'Du har ikke noe miljø å åpne ennå. :part1 :part2 :part3 for å opprette et, eller be en arbeidsområdeeier om tilgang.',
    'your_sign_in_page_gets_a_create_an_account_link_and_app_8a665905' => 'Innloggingssiden får en «Opprett konto»-lenke, og apper kan sende brukere rett til registrering med :part1.',
    'social_provider_enabled_environment' => ':provider er nå tilgjengelig på alle innloggingssidene i dette miljøet.',
    'social_provider_enabled_organization' => ':provider er nå tilgjengelig på innloggingssiden for :organization.',
    'social_provider_enabled_current_organization' => ':provider er nå tilgjengelig på organisasjonens innloggingsside.',
    'webhook_subscribed_events_count' => 'Abonnerte hendelser: :count',
